CREATE OR REPLACE FUNCTION public.nothingsports_nsc_award_points(target_user_id uuid, target_event_id text, target_action_key text, requested_points integer, awarded_time timestamp with time zone DEFAULT now())
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare award integer;fixture_total integer;day_total integer;begin
 -- reviewed-fixture-rpc-identity-v1
 target_event_id:=nothingsports_recovery.fixture_alias_v1(target_event_id);

 perform pg_advisory_xact_lock(hashtextextended('nsc-awards-v2',0));
 if requested_points<1 or requested_points>25 or target_event_id='' then return 0;end if;
 if awarded_time<(select started_at from public.nothingsports_score_epoch limit 1) then return 0;end if;
 perform pg_advisory_xact_lock(hashtextextended(target_user_id::text,0));
 if target_action_key in('heat_rating','foresight_bonus') and not exists(select 1 from public.nothingsports_predictions where user_id=target_user_id and event_id=target_event_id) then return 0;end if;
 award:=case target_action_key when 'heat_rating' then 1 when 'foresight_bonus' then 19 else requested_points end;
 if target_action_key not in('heat_rating','foresight_bonus','follow_person','followed_by_person') then
 select coalesce(sum(points),0) into fixture_total from public.nothingsports_nsc_points where user_id=target_user_id and event_id=target_event_id and action_key not in('foresight_bonus','picks_copied','follow_person','followed_by_person');
 select coalesce(sum(points),0) into day_total from public.nothingsports_nsc_points where user_id=target_user_id and sydney_day=(awarded_time at time zone 'Australia/Sydney')::date and action_key not in('foresight_bonus','picks_copied','follow_person','followed_by_person');
 award:=greatest(0,least(award,10-fixture_total,25-day_total));if award=0 then return 0;end if;
 end if;
 insert into public.nothingsports_nsc_points(user_id,event_id,action_key,points,sydney_day,awarded_at,sport)
 values(target_user_id,target_event_id,target_action_key,award,(awarded_time at time zone 'Australia/Sydney')::date,awarded_time,(select sport from public.nothingsports_score_fixtures where event_id=target_event_id)) on conflict do nothing;
 if not found then return 0;end if;return award;
end $function$

CREATE OR REPLACE FUNCTION public.nothingsports_nsc_record_unconfirmed_opinion(target_user_id uuid, target_event_id text, target_rating integer, submitted_time timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare existing public.nothingsports_nsc_contributions%rowtype;
begin
 -- reviewed-fixture-rpc-identity-v1
 target_event_id:=nothingsports_recovery.fixture_alias_v1(target_event_id);

  if target_user_id is null or coalesce(target_event_id,'')='' or target_rating not between 1 and 5 then
    raise exception 'invalid_rating';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(target_user_id::text,0));
  select * into existing from public.nothingsports_nsc_contributions
    where event_id=target_event_id and user_id=target_user_id and phase='heat'
      and bucket_start='1970-01-01T00:00:00Z'::timestamptz for update;
  if found then
    if existing.rating<>target_rating then raise exception 'nsc_already_submitted'; end if;
    return jsonb_build_object('eventId',target_event_id,'phase','heat','rating',existing.rating,
      'submitted',true,'submittedAt',existing.submitted_at,'pointsAwarded',0,'replayed',true,
      'foresightEligible',false,'timingUnconfirmed',true);
  end if;
  insert into public.nothingsports_nsc_contributions(
    event_id,user_id,phase,bucket_start,rating,tags,submitted_at,created_at,updated_at
  ) values(target_event_id,target_user_id,'heat','1970-01-01T00:00:00Z',target_rating,'{}',
    coalesce(submitted_time,now()),coalesce(submitted_time,now()),coalesce(submitted_time,now()));
  return jsonb_build_object('eventId',target_event_id,'phase','heat','rating',target_rating,
    'submitted',true,'submittedAt',coalesce(submitted_time,now()),'pointsAwarded',0,'replayed',false,
    'foresightEligible',false,'timingUnconfirmed',true);
end $function$

CREATE OR REPLACE FUNCTION public.nothingsports_nsc_submit_rating(target_user_id uuid, target_event_id text, target_phase text, target_rating integer, target_tags text[] DEFAULT '{}'::text[], submitted_time timestamp with time zone DEFAULT now())
 RETURNS TABLE(event_id text, phase text, rating smallint, tags text[], submitted_at timestamp with time zone, points_awarded integer, replayed boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  existing public.nothingsports_nsc_contributions%rowtype;
  normalized_tags text[];
  rating_points integer:=0;
  tag_points integer:=0;
  effective_time timestamptz:=coalesce(submitted_time,now());
begin
 -- reviewed-fixture-rpc-identity-v1
 target_event_id:=nothingsports_recovery.fixture_alias_v1(target_event_id);

  if target_user_id is null or coalesce(target_event_id,'')='' or target_phase is null or target_phase not in ('heat','impact') or target_rating is null or target_rating not between 1 and 5 then
    raise exception using errcode='22023',message='invalid_nsc_submission';
  end if;

  select coalesce(array_agg(item order by item),'{}'::text[])
  into normalized_tags
  from (
    select distinct item
    from unnest(coalesce(target_tags,'{}'::text[])) as expanded(item)
    where item is not null and item<>''
  ) distinct_tags;

  if cardinality(normalized_tags)>3
    or (target_rating<4 and cardinality(normalized_tags)>0)
    or (target_phase='heat' and not (normalized_tags <@ array['Box office','Big stakes','Rivalry','Star power','National interest','Great storyline']::text[]))
    or (target_phase='impact' and not (normalized_tags <@ array['Thrilling','Eye-popping','Mind-blowing','Emotional','Electric atmosphere','Pure chaos']::text[]))
  then
    raise exception using errcode='22023',message='invalid_nsc_submission';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(target_user_id::text,0));
  select contribution.* into existing
  from public.nothingsports_nsc_contributions contribution
  where contribution.event_id=target_event_id
    and contribution.user_id=target_user_id
    and contribution.phase=target_phase
    and contribution.bucket_start='1970-01-01T00:00:00Z'::timestamptz
  for update;

  if found then
    if existing.rating<>target_rating
      or not (coalesce(existing.tags,'{}'::text[]) <@ normalized_tags)
      or not (normalized_tags <@ coalesce(existing.tags,'{}'::text[]))
    then
      raise exception using errcode='P0001',message='nsc_already_submitted';
    end if;
    select coalesce(sum(point.points),0)::integer into points_awarded
    from public.nothingsports_nsc_points point
    where point.user_id=target_user_id
      and point.event_id=target_event_id
      and point.action_key in (target_phase||'_rating',target_phase||'_valid_tags');
    return query select existing.event_id,existing.phase,existing.rating,existing.tags,existing.submitted_at,points_awarded,true;
    return;
  end if;

  insert into public.nothingsports_nsc_contributions(
    event_id,user_id,phase,bucket_start,rating,tags,submitted_at,created_at,updated_at
  ) values(
    target_event_id,target_user_id,target_phase,'1970-01-01T00:00:00Z',target_rating,normalized_tags,effective_time,effective_time,effective_time
  ) returning * into existing;

  rating_points:=public.nothingsports_nsc_award_points(
    target_user_id,target_event_id,target_phase||'_rating',case when target_phase='heat' then 2 else 3 end,effective_time
  );
  if cardinality(normalized_tags)>0 then
    tag_points:=public.nothingsports_nsc_award_points(
      target_user_id,target_event_id,target_phase||'_valid_tags',1,effective_time
    );
  end if;
  points_awarded:=rating_points+tag_points;
  return query select existing.event_id,existing.phase,existing.rating,existing.tags,existing.submitted_at,points_awarded,false;
end;
$function$

CREATE OR REPLACE FUNCTION public.nothingsports_rate_v2(target_user_id uuid, target_event_id text, target_phase text, target_rating integer, fixture_start timestamp with time zone, fixture_end timestamp with time zone, fixture_status text, fixture_sport text, fixture_gender text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ts timestamptz:=clock_timestamp();expected text;award integer:=0;prior integer;begin
 -- reviewed-fixture-rpc-identity-v1
 target_event_id:=nothingsports_recovery.fixture_alias_v1(target_event_id);
 if target_event_id='rugby-australia-south-africa-2026-09-27' then fixture_start:='2026-09-27T09:45:00Z'::timestamptz;end if;

 if target_rating not between 1 and 5 or target_phase not in('heat','pulse','impact') or target_user_id is null then raise exception 'invalid_rating';end if;
 if exists(select 1 from public.nothingsports_nsc_personas where user_id=target_user_id and moderation_flag) then raise exception 'profile_moderated';end if;
 expected:=case when fixture_status in('cancelled','canceled','abandoned','postponed') then null when fixture_status in('completed','finished','final') then 'impact' when fixture_status in('live','inprogress','in_progress','in-progress') then 'pulse' when fixture_start is null or ts<fixture_start then 'heat' when ts<fixture_end then 'pulse' else 'impact' end;
 if expected is null or expected<>target_phase then raise exception 'phase_action_mismatch';end if;

 perform pg_advisory_xact_lock(hashtextextended('nsc-awards-v2',0));
 perform pg_advisory_xact_lock(hashtextextended('fixture:'||target_event_id,0));
 insert into public.nothingsports_score_fixtures values(target_event_id,fixture_sport,fixture_gender,fixture_start,fixture_end,fixture_status)
 on conflict(event_id) do update set sport=excluded.sport,gender=excluded.gender,starts_at=excluded.starts_at,ends_at=excluded.ends_at,status=excluded.status;
 select rating into prior from public.nothingsports_nsc_contributions where user_id=target_user_id and event_id=target_event_id and phase=target_phase order by updated_at desc limit 1;
 if prior=target_rating and not exists(select 1 from public.nothingsports_score_votes where user_id=target_user_id and event_id=target_event_id and phase=target_phase) then
 return jsonb_build_object('eventId',target_event_id,'phase',target_phase,'rating',target_rating,'submitted',true,'pointsAwarded',0,'replayed',true);end if;
 if target_phase='heat' then
 insert into public.nothingsports_predictions(user_id,event_id,rating,created_at,updated_at,result) values(target_user_id,target_event_id,target_rating,ts,ts,case when fixture_start is null then 'unscored' else 'pending' end)
 on conflict(user_id,event_id) do update set rating=excluded.rating,updated_at=excluded.updated_at,result=excluded.result where nothingsports_predictions.result in('pending','unscored');end if;
 insert into public.nothingsports_score_votes values(target_user_id,target_event_id,target_phase,target_rating,ts) on conflict do nothing;
 insert into public.nothingsports_nsc_contributions(event_id,user_id,phase,bucket_start,rating,tags,submitted_at,updated_at,scoring_version,maximum_points)
 values(target_event_id,target_user_id,target_phase,'1970-01-01',target_rating,'{}',ts,ts,'anticipation.v2',case when target_phase='heat' then 20 else 2 end) on conflict(event_id,user_id,phase,bucket_start) do update set rating=excluded.rating,updated_at=excluded.updated_at,scoring_version=excluded.scoring_version,maximum_points=excluded.maximum_points;
 award:=public.nothingsports_nsc_award_points(target_user_id,target_event_id,case when target_phase='pulse' then 'pulse_participation' else target_phase||'_rating' end,case when target_phase='heat' then 1 else 2 end,ts);
 if target_phase<>'heat' then perform public.nothingsports_resolve_predictions(target_event_id);end if;
 return jsonb_build_object('eventId',target_event_id,'phase',target_phase,'rating',target_rating,'submitted',true,'submittedAt',ts,'pointsAwarded',award,'basePointsAwarded',award,'foresightEligible',target_phase='heat' and fixture_start is not null);
end $function$

CREATE OR REPLACE FUNCTION public.nothingsports_resolve_predictions(target_event_id text, confirmed_end timestamp with time zone DEFAULT NULL::timestamp with time zone, final_status text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.nothingsports_prediction_rules;p record;n integer;avg_rating numeric;answer integer;outcome text;total integer:=0;begin
 -- reviewed-fixture-rpc-identity-v1
 target_event_id:=nothingsports_recovery.fixture_alias_v1(target_event_id);

 perform pg_advisory_xact_lock(hashtextextended('nsc-awards-v2',0));
 perform pg_advisory_xact_lock(hashtextextended('fixture:'||target_event_id,0));
 select * into r from public.nothingsports_prediction_rules where event_id=target_event_id;
 if r.version is distinct from 'consensus.v1' then return public.nothingsports_resolve_predictions_legacy(target_event_id,confirmed_end,final_status);end if;
 if final_status in('completed','finished','final','cancelled','canceled','abandoned') then
  update public.nothingsports_score_fixtures set status=final_status,ends_at=coalesce(r.completed_at,confirmed_end,clock_timestamp()) where event_id=target_event_id;
  select * into r from public.nothingsports_prediction_rules where event_id=target_event_id;
 end if;
 if r.settled_at is not null then return 0;end if;
 if r.cutoff is null or clock_timestamp()<r.cutoff then return 0;end if;
 for p in select x.*,f.starts_at,f.status from public.nothingsports_predictions x join public.nothingsports_score_fixtures f using(event_id) where x.event_id=target_event_id and x.result='pending' loop
  select count(*),avg(v.rating) into n,avg_rating from public.nothingsports_consensus_votes v where v.event_id=target_event_id and v.user_id<>p.user_id
   and v.recorded_at between r.completed_at and r.cutoff and not exists(select 1 from public.nothingsports_nsc_personas m where m.user_id=v.user_id and m.moderation_flag);
  answer:=round(avg_rating)::integer;
  outcome:=case when p.status in('cancelled','canceled','abandoned') then 'cancelled' when p.starts_at is null or p.updated_at>=p.starts_at or n=0 then 'unscored' when answer=p.rating then 'success' else 'miss' end;
  update public.nothingsports_predictions set result=outcome,resolved_at=clock_timestamp() where user_id=p.user_id and event_id=target_event_id;
  insert into public.nothingsports_consensus_receipts values(target_event_id,p.user_id,r.version,r.cutoff,avg_rating,answer,n,outcome) on conflict do nothing;
  -- Existing points -> inbox trigger creates the successful reward receipt atomically.
  if outcome='success' then perform public.nothingsports_nsc_award_points(p.user_id,target_event_id,'foresight_bonus',19);total:=total+1;
  else insert into public.nothingsports_inbox(recipient_user_id,kind,source_key,event_id,title,detail)
   values(p.user_id,'system','consensus:'||target_event_id,target_event_id,'Anticipation rating settled','Open your rewards for the outcome. Participation points are retained.') on conflict(recipient_user_id,source_key) do nothing;
  end if;
 end loop;
 update public.nothingsports_prediction_rules set settled_at=clock_timestamp() where event_id=target_event_id;
 return total;
end $function$

CREATE OR REPLACE FUNCTION public.nothingsports_resolve_predictions_legacy(target_event_id text, confirmed_end timestamp with time zone DEFAULT NULL::timestamp with time zone, final_status text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p record;peer uuid;has_peer boolean;total integer:=0;deadline timestamptz;begin
 -- reviewed-fixture-rpc-identity-v1
 target_event_id:=nothingsports_recovery.fixture_alias_v1(target_event_id);

 perform pg_advisory_xact_lock(hashtextextended('nsc-awards-v2',0));
 perform pg_advisory_xact_lock(hashtextextended('fixture:'||target_event_id,0));
 if final_status in('completed','finished','final','cancelled','canceled','abandoned') and confirmed_end is not null then
 update public.nothingsports_score_fixtures set ends_at=confirmed_end,status=final_status where event_id=target_event_id;
 end if;
 select ends_at+interval '48 hours' into deadline from public.nothingsports_score_fixtures where event_id=target_event_id and status in('completed','finished','final','cancelled','canceled','abandoned');
 for p in select x.*,f.starts_at,f.status from public.nothingsports_predictions x join public.nothingsports_score_fixtures f using(event_id) where x.event_id=target_event_id and x.result='pending' and x.updated_at<f.starts_at loop
 if p.status in('cancelled','canceled','abandoned') then
 update public.nothingsports_predictions set result='cancelled',resolved_at=clock_timestamp() where user_id=p.user_id and event_id=target_event_id;continue;end if;
 select v.user_id into peer from public.nothingsports_score_votes v where v.event_id=target_event_id and v.user_id<>p.user_id and v.phase in('pulse','impact') and v.rating=p.rating and v.recorded_at>=p.starts_at and (deadline is null or v.recorded_at<=deadline)
 and not exists(select 1 from public.nothingsports_nsc_personas m where m.user_id=v.user_id and m.moderation_flag) order by v.recorded_at limit 1;
 if peer is not null then
 update public.nothingsports_predictions set result='success',matched_user_id=peer,resolved_at=clock_timestamp() where user_id=p.user_id and event_id=target_event_id;
 perform public.nothingsports_nsc_award_points(p.user_id,target_event_id,'foresight_bonus',19);total:=total+1;
 elsif deadline is not null and clock_timestamp()>=deadline then
 select exists(select 1 from public.nothingsports_score_votes v where v.event_id=target_event_id and v.user_id<>p.user_id and v.phase in('pulse','impact') and v.recorded_at between p.starts_at and deadline and not exists(select 1 from public.nothingsports_nsc_personas m where m.user_id=v.user_id and m.moderation_flag)) into has_peer;
 update public.nothingsports_predictions set result=case when has_peer then 'miss' else 'unscored' end,resolved_at=clock_timestamp() where user_id=p.user_id and event_id=target_event_id;
 end if;
 end loop;return total;
end $function$

CREATE OR REPLACE FUNCTION public.nothingsports_set_reminder_choice(target_user uuid, fixture_key text, fixture_aliases jsonb, enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
 SET statement_timeout TO '3s'
AS $function$
declare row public.nothingsports_user_state;stamp timestamptz:=clock_timestamp();begin
 if exists(select 1 from public.nothingsports_account_erasure_blocks where user_id=target_user) then raise exception 'Account unavailable';end if;
 if length(fixture_key) not between 1 and 180 or jsonb_typeof(fixture_aliases)<>'array' or jsonb_array_length(fixture_aliases)>30 then raise exception 'Invalid fixture';end if;
 select * into row from public.nothingsports_user_state where user_id=target_user for update;
 if not found then raise exception 'Saved account state required';end if;
 stamp:=greatest(stamp,row.updated_at+interval '1 millisecond');
 insert into public.nothingsports_reminder_intents(user_id,fixture_id,aliases,choice,enabled,chosen_at)
 values(target_user,fixture_key,fixture_aliases,case when enabled then 'on' else 'off' end,enabled,stamp)
 on conflict(user_id,fixture_id) do update set aliases=excluded.aliases,choice=excluded.choice,enabled=excluded.enabled,chosen_at=excluded.chosen_at;
 update public.nothingsports_user_state set event_user_state=jsonb_set(coalesce(event_user_state,'{}'),array[fixture_key],coalesce(event_user_state->fixture_key,'{}')||jsonb_build_object('actionKey',fixture_key,'canonicalEventId',fixture_key,'reminderRequested',enabled,'reminderChoice',case when enabled then 'on' else 'off' end,'reminderChangedAt',stamp,'lastActionAt',stamp)),updated_at=stamp where user_id=target_user;
 if not enabled then update public.nothingsports_reminders set schedule_state='off',claimed_at=null,updated_at=stamp where user_id=target_user and dispatched_at is null and (event_id=fixture_key or fixture_aliases ? event_id);end if;
end $function$

CREATE OR REPLACE FUNCTION public.nothingsports_sync_reminder_choices()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a record;key text;stamp timestamptz;existing public.nothingsports_reminder_intents;begin
 if exists(select 1 from public.nothingsports_account_erasure_blocks b where b.user_id=new.user_id) then return new;end if;
 for a in select * from jsonb_each(coalesce(new.event_user_state,'{}')) loop
  if a.value->>'reminderChoice' is null and a.value ? 'reminderRequested' and (tg_op='INSERT' or (old.event_user_state->a.key->>'reminderRequested') is distinct from (a.value->>'reminderRequested')) then
   a.value:=a.value||jsonb_build_object('reminderChoice',case when a.value->>'reminderRequested'='true' then 'on' else 'off' end,'reminderChangedAt',a.value->>'lastActionAt');
  end if;
  if a.value->>'reminderChoice' not in('on','off') then continue;end if;
  if (a.value->>'reminderChangedAt') is null then continue;end if;
  begin stamp:=(a.value->>'reminderChangedAt')::timestamptz;exception when others then continue;end;
  if stamp>clock_timestamp()+interval '5 minutes' then continue;end if;
  select * into existing from public.nothingsports_reminder_intents i where i.user_id=new.user_id and (i.fixture_id=a.key or i.aliases ? a.key) order by i.chosen_at desc nulls last limit 1;
  key:=coalesce(existing.fixture_id,a.value->>'canonicalEventId',a.key);
  if existing.chosen_at is not null and stamp<existing.chosen_at then
   new.event_user_state:=jsonb_set(new.event_user_state,array[a.key],a.value||jsonb_build_object('reminderChoice',existing.choice,'reminderRequested',existing.choice='on','reminderChangedAt',existing.chosen_at));continue;
  end if;
  insert into public.nothingsports_reminder_intents(user_id,fixture_id,aliases,choice,enabled,chosen_at)
   values(new.user_id,key,coalesce(existing.aliases,jsonb_build_array(a.key)),a.value->>'reminderChoice',a.value->>'reminderChoice'='on',stamp)
   on conflict(user_id,fixture_id) do update set choice=excluded.choice,enabled=excluded.enabled,chosen_at=excluded.chosen_at;
  if a.value->>'reminderChoice'='off' then
   update public.nothingsports_reminders set schedule_state='off',claimed_at=null,updated_at=clock_timestamp()
    where user_id=new.user_id and dispatched_at is null and (event_id=key or coalesce(existing.aliases,'[]') ? event_id);
  end if;
 end loop;return new;
end $function$

CREATE OR REPLACE FUNCTION public.nothingsports_reconcile_reminder_accounts(packets jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
 SET statement_timeout TO '3s'
AS $function$
declare p record;f record;s public.nothingsports_user_state;i public.nothingsports_reminder_intents;stamp timestamptz:=clock_timestamp();changed integer:=0;alerts boolean;begin
 if jsonb_typeof(packets)<>'array' or jsonb_array_length(packets)>20 then raise exception 'Invalid account batch';end if;
 for p in select * from jsonb_to_recordset(packets) x(user_id uuid,expected_updated timestamptz,items jsonb) loop
  if jsonb_typeof(p.items)<>'array' or jsonb_array_length(p.items)>100 then raise exception 'Invalid fixture batch';end if;
  select * into s from public.nothingsports_user_state where user_id=p.user_id and updated_at=p.expected_updated for update skip locked;
  if not found or exists(select 1 from public.nothingsports_account_erasure_blocks b where b.user_id=p.user_id) then continue;end if;
  alerts:=coalesce(s.preferences#>>'{followFirst,notifications,enabled}','true')<>'false' and coalesce(s.preferences#>>'{followFirst,notifications,sportingRemindersEnabled}','true')<>'false';
  for f in select * from jsonb_to_recordset(p.items) x(fixture_id text,aliases jsonb,choice text,enabled boolean,title text,starts_at timestamptz,precision text) loop
   if f.choice not in('automatic','on','off') or f.precision not in('exact','not-before') or length(f.fixture_id) not between 1 and 180 then raise exception 'Invalid decision';end if;
   if exists(select 1 from public.nothingsports_reminders r where r.user_id=p.user_id and (r.event_id=f.fixture_id or f.aliases ? r.event_id) and r.claimed_at>=stamp-interval '10 minutes' and r.dispatched_at is null) then continue;end if;
   select * into i from public.nothingsports_reminder_intents where user_id=p.user_id and fixture_id=f.fixture_id;
   if i.choice in('on','off') and i.choice<>f.choice then continue;end if;
   insert into public.nothingsports_reminder_intents(user_id,fixture_id,aliases,choice,enabled,state_revision,checked_at)
   values(p.user_id,f.fixture_id,f.aliases,f.choice,f.enabled,p.expected_updated,stamp) on conflict(user_id,fixture_id) do update set aliases=excluded.aliases,choice=excluded.choice,enabled=excluded.enabled,state_revision=excluded.state_revision,checked_at=excluded.checked_at where (public.nothingsports_reminder_intents.aliases,public.nothingsports_reminder_intents.choice,public.nothingsports_reminder_intents.enabled,public.nothingsports_reminder_intents.state_revision) is distinct from (excluded.aliases,excluded.choice,excluded.enabled,excluded.state_revision);
   if f.enabled and alerts and f.starts_at>stamp then
    -- Old aliases carry their receipt forward. Neither rescheduling nor a second
    -- surface may create another delivery for a fixture already dispatched.
    update public.nothingsports_reminders r set event_id=f.fixture_id where r.user_id=p.user_id and f.aliases ? r.event_id and r.event_id<>f.fixture_id and not exists(select 1 from public.nothingsports_reminders n where n.installation_id=r.installation_id and n.event_id=f.fixture_id);
    insert into public.nothingsports_reminders(installation_id,user_id,event_id,title,starts_at,remind_at,delivery_mode,viewing_url,reminder_origin,timing_precision,schedule_checked_at,schedule_state,schedule_starts_at,late_published_at)
    select d.installation_id,p.user_id,f.fixture_id,left(f.title,180),f.starts_at,f.starts_at-interval '15 minutes','match-15',null,case when f.choice='automatic' then 'automatic' else 'manual' end,f.precision,stamp,'ready',f.starts_at,case when f.starts_at-interval '15 minutes'<stamp then stamp end
    from public.nothingsports_push_installations d where d.user_id=p.user_id and d.permission='granted' and d.sporting_reminders_enabled
    on conflict(installation_id,event_id) do update set title=excluded.title,starts_at=excluded.starts_at,remind_at=excluded.remind_at,reminder_origin=excluded.reminder_origin,timing_precision=excluded.timing_precision,schedule_checked_at=stamp,schedule_state='ready',schedule_starts_at=excluded.starts_at,late_published_at=coalesce(public.nothingsports_reminders.late_published_at,excluded.late_published_at),updated_at=stamp
     where public.nothingsports_reminders.dispatched_at is null and public.nothingsports_reminders.delivery_started_at is null and (public.nothingsports_reminders.claimed_at is null or public.nothingsports_reminders.claimed_at<stamp-interval '10 minutes') and (public.nothingsports_reminders.starts_at,public.nothingsports_reminders.schedule_state,public.nothingsports_reminders.timing_precision,public.nothingsports_reminders.reminder_origin) is distinct from (excluded.starts_at,'ready',excluded.timing_precision,excluded.reminder_origin);
   -- Fold receipts from any second surface before removing its delivery row.
    update public.nothingsports_reminders r set delivery_started_at=coalesce(r.delivery_started_at,(select min(a.delivery_started_at) from public.nothingsports_reminders a where a.installation_id=r.installation_id and f.aliases ? a.event_id)),dispatched_at=coalesce(r.dispatched_at,(select min(a.dispatched_at) from public.nothingsports_reminders a where a.installation_id=r.installation_id and f.aliases ? a.event_id)) where r.user_id=p.user_id and r.event_id=f.fixture_id;
    delete from public.nothingsports_reminders r where r.user_id=p.user_id and f.aliases ? r.event_id and r.event_id<>f.fixture_id;
   else
    update public.nothingsports_reminders set schedule_state='held',schedule_checked_at=stamp,schedule_starts_at=null,claimed_at=null,updated_at=stamp where user_id=p.user_id and (event_id=f.fixture_id or f.aliases ? event_id) and dispatched_at is null and schedule_state is distinct from 'held' and (claimed_at is null or claimed_at<stamp-interval '10 minutes');
   end if;
   changed:=changed+1;
  end loop;
  insert into public.nothingsports_reminder_account_checks values(p.user_id,stamp) on conflict(user_id) do update set checked_at=excluded.checked_at;
 end loop;return changed;
end $function$
